scripts.preRequest:
// **********************************************
// 🛠️ Learn more about scripts and snippets: https://docs.requestly.com/general/api-client/scripts
// **********************************************
require pm

pm.request.headers.add({
    key: "Authorization",
    value: "Bearer " + pm.collectionVariables.get("access_token")
});

scripts.postResponse:
// **********************************************
// 🛠️ Use JavaScript to visualize responses: https://docs.requestly.com/general/api-client/scripts
// **********************************************
let response = pm.response.json();

if (response.access_token) {
    pm.collectionVariables.set("access_token", response.access_token);
    console.log("Access token saved:", response.access_token);
}
